class Solution:
    def minCut(self, s: str) -> int:
        def is_pal(x):
            return x == x[::-1]
        def dfs(i):
            if i == len(s):
                return 0
            best = len(s) - i
            for j in range(i + 1, len(s) + 1):
                if is_pal(s[i:j]):
                    best = min(best, 1 + dfs(j))
            return best
        return dfs(0) - 1

