class Solution:
    def minCut(self, s):
        n = len(s)
        cuts = [i - 1 for i in range(n + 1)]
        for c in range(n):
            l = r = c
            while l >= 0 and r < n and s[l] == s[r]:
                cuts[r + 1] = min(cuts[r + 1], cuts[l] + 1)
                l -= 1; r += 1
            l, r = c, c + 1
            while l >= 0 and r < n and s[l] == s[r]:
                cuts[r + 1] = min(cuts[r + 1], cuts[l] + 1)
                l -= 1; r += 1
        return cuts[n]

